use crate::shader_const::Vertex;
use coppervox_analyzer::{
    QuadsReader,
    block_mesh::{QuadBuffer, QuadCoordinateConfig},
};
use std::rc::Rc;

/// A mesh made of vertices and triangle indices, ready to be uploaded to the GPU.
/// Indices are local to this mesh (start at 0); a `base_vertex` offset is applied
/// when the mesh is copied into the global vertex/index buffers.
pub struct Mesh {
    /// Vertices composing the mesh
    pub vertices: Vec<Vertex>,

    /// Triangle indices, local to this mesh's vertex buffer
    pub indices: Vec<u32>,
}

/// Read the quad data generated by `block_mesh` and turn it into a flat-shaded [`Mesh`]
pub struct QuadDataReader;

impl QuadDataReader {
    /// Create a new quad reader
    #[inline]
    pub fn new() -> Self {
        Self
    }
}

impl Default for QuadDataReader {
    #[inline]
    fn default() -> Self {
        Self::new()
    }
}

impl QuadsReader<Rc<Mesh>> for QuadDataReader {
    /// Read the data generated by block_mesh and build a mesh from it.
    /// Each quad gets its own 4 vertices (flat shading) instead of sharing
    /// vertices across faces, so no separate normal index is needed.
    fn read_quads(&mut self, quads: &QuadBuffer, config: &QuadCoordinateConfig) -> Rc<Mesh> {
        let count = quads.num_quads();
        let mut vertices = Vec::with_capacity(count * 4);
        let mut indices = Vec::with_capacity(count * 6);

        for (group, face) in quads.groups.iter().zip(&config.faces) {
            let normal = face.signed_normal().as_vec3().to_array();

            for quad in group.iter() {
                let base = vertices.len() as u32;

                for &position in face.quad_mesh_positions(quad, 1.0).iter() {
                    vertices.push(Vertex { position, normal });
                }

                indices.extend_from_slice(&face.quad_mesh_indices(base));
            }
        }

        Rc::new(Mesh { vertices, indices })
    }
}
